[IO.File]::WriteAllText((Join-Path $PWD 'test-run.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# One test run: start surl's S3 endpoint on a free port with a random seed, run the app's`n# upload against it, stop surl, and exit with the app's code. The seed is printed first, so a`n# failed run's log says how to repeat it.`n# Usage: sh test-run.sh [<seed>] [probe]     (no seed: draw one; probe: connect once first)`nseed=`${1:-`$(od -An -N4 -tu4 /dev/urandom | tr -d ' ')}`necho `"seed=`$seed`"`nrm -rf store && mkdir -p store/photos`n: > listening.txt`nsurl -v --s3-plaintext --random-seed `"`$seed`" --directory store \`n  --user AKIAIOSFODNN7EXAMPLE:s3cret --allow-uploads s3://127.0.0.1:0/ > listening.txt 2> surl.log &`npid=`$!`n`n# Wait for the Listening on line; a surl that exits first refused to start.`ntries=0`nuntil grep -q '^Listening on ' listening.txt; do`n  if ! kill -0 `"`$pid`" 2>/dev/null; then wait `"`$pid`"; code=`$?; cat surl.log >&2; exit `"`$code`"; fi`n  tries=`$((tries + 1))`n  if [ `"`$tries`" -ge 100 ]; then kill `"`$pid`"; echo `"surl did not start in 10 s`" >&2; exit 1; fi`n  sleep 0.1`ndone`nurl=`$(sed -n 's|^Listening on s3://|http://|p' listening.txt | tr -d '\r')`n`n# A readiness check that connects is one more exchange before the app's.`nif [ `"`$2`" = probe ]; then curl -s -o /dev/null `"`$url`"; fi`n`nsh upload.sh `"`$url`"`nresult=`$?`nkill `"`$pid`" 2>/dev/null; wait `"`$pid`" 2>/dev/null`nexit `"`$result`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'upload.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# The app under test, as a script: a multipart upload of big.bin into the photos bucket.`n# Usage: sh upload.sh <S3 endpoint URL>`nsign=`"--aws-sigv4 aws:amz:us-east-1:s3 -u AKIAIOSFODNN7EXAMPLE:s3cret`"`nid=`$(curl -sS `$sign -X POST `"`${1}photos/big.bin?uploads`" |`n  sed -n 's|.*<UploadId>\([0-9a-f]*\)</UploadId>.*|\1|p')`necho `"upload `$id`"`n`n# The bug the test run trips over, standing in for your app's: it uses the upload ID as a`n# name, and a name may not begin with a digit. Only some IDs bring it out.`ncase `$id in`n  [0-9]*) echo `"failed: upload `$id cannot be named`" >&2; exit 1 ;;`nesac`n`nprintf 'part one\n' > part1.bin`netag=`$(curl -sS `$sign -D - -o /dev/null -T part1.bin `"`${1}photos/big.bin?partNumber=1&uploadId=`$id`" |`n  tr -d '\r' | sed -n 's/^[Ee][Tt]ag: //p')`nprintf '<CompleteMultipartUpload><Part><PartNumber>1</PartNumber><ETag>%s</ETag></Part></CompleteMultipartUpload>' \`n  `"`$etag`" > complete.xml`ncurl -sS -f `$sign -o /dev/null --data-binary @complete.xml `"`${1}photos/big.bin?uploadId=`$id`" || exit`necho `"stored big.bin`"`n")
[IO.File]::WriteAllText((Join-Path $PWD 'nonces.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Starts two HTTP servers with the same seed and one account, asks each for a file without a`n# login, and says whether the Digest nonces of their 401s are the same.`nfor n in 1 2; do`n  : > `"http-`$n.txt`"`n  surl --random-seed 3 --user alice:s3cret http://127.0.0.1:0/ > `"http-`$n.txt`" 2> /dev/null &`n  echo `$! > `"http-`$n.pid`"`ndone`nfor n in 1 2; do`n  tries=0`n  until grep -q '^Listening on ' `"http-`$n.txt`"; do`n    tries=`$((tries + 1)); [ `"`$tries`" -lt 100 ] || break; sleep 0.1`n  done`n  url=`$(sed -n 's|^Listening on ||p' `"http-`$n.txt`" | tr -d '\r')`n  curl -s -o /dev/null -D - `"`${url}a.txt`" | sed -n 's/.*nonce=`"\([0-9a-f]*\)`".*/\1/p' | head -n 1 > `"nonce-`$n.txt`"`n  kill `"`$(cat `"http-`$n.pid`")`"`ndone`nif [ -s nonce-1.txt ] && cmp -s nonce-1.txt nonce-2.txt; then echo `"same nonce`"; else echo `"different nonces`"; fi`n")
